import{_ as n}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{C as l,c as d,o as e,af as a,b as i,w as r,a as s,G as h,ag as E}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const k=JSON.parse('{"title":"Production 组","description":"功能跑通不等于可以上线——本组用测试、评估、可观测性、安全、成本与部署六类证据，把「能演示」变成「能运营、能回放、能追责」。","frontmatter":{"title":"Production 组","description":"功能跑通不等于可以上线——本组用测试、评估、可观测性、安全、成本与部署六类证据，把「能演示」变成「能运营、能回放、能追责」。","domain":"tech","tags":["tech","operations"],"navOrder":80,"topicId":"operations-index","layer":"8","status":"canonical","nodeType":"problem","owner":"learn-ai","externalOwners":[],"prerequisites":["agent-recovery-hitl"],"next":["testing","evaluation","observability","security","cost-performance","deployment","resources","agentops"],"specVersion":"","lastVerified":"2026-09-01","bilingualParity":"exact","listed":true},"headers":[],"relativePath":"zh/tech/08-production/index.md","filePath":"zh/tech/08-production/index.md","lastUpdated":1791165915000}'),c={name:"zh/tech/08-production/index.md"};function g(m,t,u,p,A,b){const o=l("Mermaid");return e(),d("div",null,[t[1]||(t[1]=a('<blockquote><p><strong>所在组</strong>：Production ｜ <strong>上一组出口</strong>：能限制权限、暂停/恢复任务 ｜ <strong>本组出口</strong>：能用可回放证据说明质量、风险、性能、回滚和责任人 <strong>前置</strong>：<a href="./../06-agent-systems/recovery-hitl.html">恢复与人工批准</a> ｜ <strong>下一步</strong>：<a href="./testing.html">测试</a>、<a href="./evaluation.html">评估（桥接）</a>、<a href="./observability.html">可观测性</a>、<a href="./security.html">安全</a>、<a href="./cost-performance.html">成本与性能</a>、<a href="./deployment.html">部署与发布</a>，出组后进<a href="./../../resources.html">资料库</a></p></blockquote><h2 id="_1-概述" tabindex="-1">1. 概述 <a class="header-anchor" href="#_1-概述" aria-label="Permalink to &quot;1. 概述&quot;">​</a></h2><p><strong>结论先讲</strong>：「功能已跑通」与「可以上线运营」之间隔着一整组工作。演示只需要一次成功；运营需要<strong>可回放的证据</strong>——出问题时能重放当时发生了什么、改动前能预测影响、故障时有明确的责任人和回滚路径。本组把上游各组散落的工程手段收口为五类上线证据：质量、风险、性能、回滚、责任人。</p><h3 id="心智模型-六条证据链" tabindex="-1">心智模型：六条证据链 <a class="header-anchor" href="#心智模型-六条证据链" aria-label="Permalink to &quot;心智模型：六条证据链&quot;">​</a></h3>',4)),(e(),i(E,null,{default:r(()=>[h(o,{id:"mermaid-14",class:"mermaid",graph:"flowchart%20TB%0A%20%20%20%20Q%5B%22Production%20%E7%BB%84%E7%9A%84%E9%97%AE%E9%A2%98%EF%BC%9A%E5%A6%82%E4%BD%95%E8%AF%81%E6%98%8E%E5%AE%83%E5%8F%AF%E4%BB%A5%E4%B8%8A%E7%BA%BF%E5%B9%B6%E6%8C%81%E7%BB%AD%E8%BF%90%E8%A1%8C%EF%BC%9F%22%5D%0A%20%20%20%20Q%20--%3E%20T%5B%22%E6%B5%8B%E8%AF%95%3Cbr%2F%3E%E7%A1%AE%E5%AE%9A%E6%80%A7%E5%8F%AF%E6%96%AD%E8%A8%80%E7%9A%84%E8%A1%8C%E4%B8%BA%E8%BE%B9%E7%95%8C%22%5D%0A%20%20%20%20Q%20--%3E%20E%5B%22%E8%AF%84%E4%BC%B0%EF%BC%88%E6%A1%A5%E6%8E%A5%EF%BC%89%3Cbr%2F%3E%E6%A6%82%E7%8E%87%E6%80%A7%E8%B4%A8%E9%87%8F%E8%AF%81%E6%8D%AE%20%E2%86%92%20evals%20%E7%AB%99%22%5D%0A%20%20%20%20Q%20--%3E%20O%5B%22%E5%8F%AF%E8%A7%82%E6%B5%8B%E6%80%A7%3Cbr%2F%3E%E8%BD%A8%E8%BF%B9%E5%8F%AF%E5%9B%9E%E6%94%BE%E3%80%81%E5%8F%AF%E5%BD%92%E5%9B%A0%22%5D%0A%20%20%20%20Q%20--%3E%20S%5B%22%E5%AE%89%E5%85%A8%3Cbr%2F%3E%E4%B8%89%E5%B1%82%E9%A3%8E%E9%99%A9%E7%9A%84%E5%B7%A5%E7%A8%8B%E8%BE%B9%E7%95%8C%22%5D%0A%20%20%20%20Q%20--%3E%20C%5B%22%E6%88%90%E6%9C%AC%E4%B8%8E%E6%80%A7%E8%83%BD%3Cbr%2F%3E%E5%8D%95%E4%BD%8D%E7%BB%8F%E6%B5%8E%E4%B8%8E%E5%BB%B6%E8%BF%9F%E5%88%86%E8%A7%A3%22%5D%0A%20%20%20%20Q%20--%3E%20D%5B%22%E9%83%A8%E7%BD%B2%E4%B8%8E%E5%8F%91%E5%B8%83%3Cbr%2F%3E%E5%8F%91%E5%B8%83%E9%97%A8%E3%80%81%E5%9B%9E%E6%BB%9A%E3%80%81%E8%BF%90%E8%A1%8C%E6%89%8B%E5%86%8C%22%5D%0A%20%20%20%20T%20%26%20E%20%26%20O%20%26%20S%20%26%20C%20%26%20D%20--%3E%20X%5B%22%E5%87%BA%E5%8F%A3%EF%BC%9A%E8%B4%A8%E9%87%8F%20%2F%20%E9%A3%8E%E9%99%A9%20%2F%20%E6%80%A7%E8%83%BD%20%2F%20%E5%9B%9E%E6%BB%9A%20%2F%20%E8%B4%A3%E4%BB%BB%E4%BA%BA%3Cbr%2F%3E%E4%BA%94%E7%B1%BB%E8%AF%81%E6%8D%AE%E9%BD%90%E5%A4%87%22%5D%0A"})]),fallback:r(()=>[...t[0]||(t[0]=[s(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=a('<p>六条链不是六道顺序工序，而是同一批工件的六个切面：一条 trace 既是观测证据，也是成本证据，也是事故回放的素材。</p><h3 id="症状路由表" tabindex="-1">症状路由表 <a class="header-anchor" href="#症状路由表" aria-label="Permalink to &quot;症状路由表&quot;">​</a></h3><table tabindex="0"><thead><tr><th>症状（「功能已跑但……」）</th><th>去哪章</th><th>那章给你的证据</th></tr></thead><tbody><tr><td>改一处 prompt，不知道坏了什么</td><td><a href="./testing.html">测试</a></td><td>确定性测试金字塔：改动的可断言影响面</td></tr><tr><td>「变好/变坏」只能靠感觉说</td><td><a href="./evaluation.html">评估（桥接）</a></td><td>golden set + 阈值的发布门（方法论 → evals 站）</td></tr><tr><td>线上出问题，只能看零散日志猜</td><td><a href="./observability.html">可观测性</a></td><td>trace/span + correlation ID 的可回放轨迹</td></tr><tr><td>担心注入、越权、泄露，但只有「模型会拒绝」</td><td><a href="./security.html">安全</a></td><td>输入过滤 + 权限边界 + 输出扫描的组合防线</td></tr><tr><td>月账单和 P95 延迟没人能解释</td><td><a href="./cost-performance.html">成本与性能</a></td><td>每请求成本追踪 + 延迟分解 + 优化阶梯</td></tr><tr><td>发布靠手动拷贝，回滚靠记忆</td><td><a href="./deployment.html">部署与发布</a></td><td>发布门链、版本化回滚、运行手册</td></tr></tbody></table><h3 id="决策表-五类证据的取证方式对比" tabindex="-1">决策表：五类证据的取证方式对比 <a class="header-anchor" href="#决策表-五类证据的取证方式对比" aria-label="Permalink to &quot;决策表：五类证据的取证方式对比&quot;">​</a></h3><table tabindex="0"><thead><tr><th>证据类型</th><th>方向</th><th>控制权</th><th>状态</th><th>信任域</th><th>最低复杂度</th></tr></thead><tbody><tr><td>质量（测试 + 评估）</td><td>读</td><td>你写断言/数据集</td><td>fixture + golden set</td><td>CI 进程内</td><td>一个 node:test 文件</td></tr><tr><td>风险（安全）</td><td>读写</td><td>过滤器 + 权限边界 + 审计</td><td>规则 + 审计日志</td><td>应用信任域</td><td>一层输入/输出过滤</td></tr><tr><td>性能（成本 + 延迟）</td><td>读</td><td>采样与预算配置</td><td>时序指标</td><td>观测后端</td><td>每请求 usage 记账</td></tr><tr><td>回滚（部署）</td><td>写</td><td>版本 + 切流开关</td><td>版本化工件</td><td>部署信任域</td><td>版本号 + 双写开关</td></tr><tr><td>责任人（运行手册）</td><td>—</td><td>值班表 + 升级路径</td><td>文档 + 告警路由</td><td>组织</td><td>一页谁负责什么</td></tr></tbody></table><h3 id="横切声明" tabindex="-1">横切声明 <a class="header-anchor" href="#横切声明" aria-label="Permalink to &quot;横切声明&quot;">​</a></h3><p>安全、成本、观测<strong>不是本组才出现的话题</strong>：权限边界在<a href="./../05-action/tool-execution.html">工具执行</a>就已引入，token 用量在<a href="./../02-inference-interface/model-api.html">模型 API</a> 的 usage 字段就已返回，脱敏在<a href="./../03-context/context-engineering.html">上下文工程</a>就要考虑。上游各组在各自场景里就地处理这些关注点；<strong>Production 组把它们收口为系统性的上线证据</strong>——不再是「某处做对了」，而是「处处可证明」。</p><h3 id="何时使用-何时不用" tabindex="-1">何时使用 / 何时不用 <a class="header-anchor" href="#何时使用-何时不用" aria-label="Permalink to &quot;何时使用 / 何时不用&quot;">​</a></h3><ul><li>用：任何要越过「个人 demo」进入「有用户、有值班、有账单」的系统。</li><li>不用：一次性脚本、本地实验、学习性玩具——为它们建设五类证据是过度工程。判断依据见<a href="./../00-map/complexity-ladder.html">复杂度决策阶梯</a>。</li></ul><p>历史版本里程碑：本组结构于 2026-09 随 Issue #116 冻结，由旧 <code>engineering/</code>（testing/evals/observability/security/cost-optimization）与 <code>testing/</code>、<code>evaluation/</code> 目录合并升级；更早来源未验证，不编造。</p><h2 id="_2-使用" tabindex="-1">2. 使用 <a class="header-anchor" href="#_2-使用" aria-label="Permalink to &quot;2. 使用&quot;">​</a></h2><p>本页是路由层，无可运行代码产物；「使用」= 上线就绪自检演练（纸面即可，≤15 分钟）。验收标准：对你要上线的系统，五类证据全部能落到「具体工件 + 责任人」，写不出的一栏就是你的缺口。</p><h3 id="演练-五问审计" tabindex="-1">演练：五问审计 <a class="header-anchor" href="#演练-五问审计" aria-label="Permalink to &quot;演练：五问审计&quot;">​</a></h3><p>对目标系统依次回答，记录「证据在哪（文件/看板/文档）」与「谁负责」：</p><ol><li><strong>质量</strong>：最近一次 prompt 改动，CI 里哪些测试跑了？评估分数变了多少？（→ <a href="./testing.html">测试</a> / <a href="./evaluation.html">评估</a>）</li><li><strong>风险</strong>：一条注入 payload 打进输入端点，会被哪一层拦住？拦截记录在哪？（→ <a href="./security.html">安全</a>）</li><li><strong>性能</strong>：随机挑一条昨天的线上请求，能在一分钟内找到它的 token 成本和各段耗时吗？（→ <a href="./observability.html">可观测性</a> / <a href="./cost-performance.html">成本与性能</a>）</li><li><strong>回滚</strong>：当前版本的上一版是什么？切回去要执行哪几个动作？（→ <a href="./deployment.html">部署与发布</a>）</li><li><strong>责任人</strong>：凌晨两点模型厂商 5xx，值班的人第一眼看哪个仪表盘、第一个动作是什么？（→ <a href="./deployment.html">部署与发布</a> 的运行手册）</li></ol><h3 id="使用边界" tabindex="-1">使用边界 <a class="header-anchor" href="#使用边界" aria-label="Permalink to &quot;使用边界&quot;">​</a></h3><ul><li>本组不教你「怎么写测试/怎么埋点」——那是六个子章的内容；本页只负责把症状路由到正确的证据链。</li><li>五类证据的<strong>深度</strong>按业务风险缩放：内部工具不需要金融级审计日志，但需要能回答上面五问的最低版本。</li></ul><h2 id="_3-原理" tabindex="-1">3. 原理 <a class="header-anchor" href="#_3-原理" aria-label="Permalink to &quot;3. 原理&quot;">​</a></h2><h3 id="为什么「收口」发生在-production-组" tabindex="-1">为什么「收口」发生在 Production 组 <a class="header-anchor" href="#为什么「收口」发生在-production-组" aria-label="Permalink to &quot;为什么「收口」发生在 Production 组&quot;">​</a></h3><p>上游每一组的出口都是「跑通」：schema 校验通过、端到端可取消、检索可追溯、权限可暂停恢复。但「跑通」是<strong>单次属性</strong>；运营要求的是<strong>持续属性</strong>——第一百次请求和第一次一样可靠，第七次改动和第一次一样可预测。把单次属性升级为持续属性的手段就是证据化：</p><ul><li>行为的可预测性 ← 测试 + 评估（改动前后可比）</li><li>故障的可解释性 ← 可观测性（轨迹可回放）</li><li>边界的可验证性 ← 安全（攻击路径有拦截记录）</li><li>资用的可核算性 ← 成本与性能（每请求可记账）</li><li>变更的可逆性 ← 部署（版本可切回）</li></ul><h3 id="可回放性是本组的统一不变量" tabindex="-1">可回放性是本组的统一不变量 <a class="header-anchor" href="#可回放性是本组的统一不变量" aria-label="Permalink to &quot;可回放性是本组的统一不变量&quot;">​</a></h3><p>五类证据共享同一个验收标准：<strong>事后能重放</strong>。测试可重跑、评估数据集可复现、trace 可导出重看、攻击样本可重放到过滤器、成本可按请求重算、版本可重新部署。任何「当时看到了、现在找不回」的观测都不算证据——这是区分真观测与「碰巧看见」的分界线。</p><h3 id="与外部-owner-的分工" tabindex="-1">与外部 owner 的分工 <a class="header-anchor" href="#与外部-owner-的分工" aria-label="Permalink to &quot;与外部 owner 的分工&quot;">​</a></h3><p>本组有两处刻意停止：评估方法论（数据集/scorer/judge/统计/红队）由 <a href="https://evals.zenheart.site/" target="_blank" rel="noreferrer">evals</a> 拥有，本仓只回答「何时需要证据、如何接入发布门」；模型对齐层的风险机理（reward hacking、越狱倾向）由 <a href="https://llm.zenheart.site/" target="_blank" rel="noreferrer">Learn LLM</a> 拥有，本仓只做应用侧工程。分工细节见 <code>_phase0/bridge-register.md</code>。</p><h3 id="规范要求-vs-本地实测" tabindex="-1">规范要求 vs 本地实测 <a class="header-anchor" href="#规范要求-vs-本地实测" aria-label="Permalink to &quot;规范要求 vs 本地实测&quot;">​</a></h3><p>本页是路由层，无规范可实现测；六个子章各自携带「规范 vs 实测」分栏（如 OTel GenAI 语义约定、OWASP 2026 清单、Vitest 版本要求）。</p><h2 id="_4-开发" tabindex="-1">4. 开发 <a class="header-anchor" href="#_4-开发" aria-label="Permalink to &quot;4. 开发&quot;">​</a></h2><p>本页无代码集成；「开发」= 把五问审计用作上线评审门。</p><h3 id="症状-→-证据-→-处理-→-完成标准" tabindex="-1">症状 → 证据 → 处理 → 完成标准 <a class="header-anchor" href="#症状-→-证据-→-处理-→-完成标准" aria-label="Permalink to &quot;症状 → 证据 → 处理 → 完成标准&quot;">​</a></h3><p><strong>症状</strong>：评审被一句「你怎么证明它是对的？」打回，团队只能重演 demo。 <strong>证据</strong>：评审材料里没有五问审计表；改动历史与线上行为之间没有可对账的工件。 <strong>处理</strong>：填写五问审计，任何答不出的一栏先补最低版本（一个测试文件、一条 trace、一页运行手册都算）。 <strong>完成标准</strong>：评审材料包含五问审计表，每栏有具体工件路径与责任人姓名。</p><h3 id="症状-→-证据-→-处理-→-完成标准-1" tabindex="-1">症状 → 证据 → 处理 → 完成标准 <a class="header-anchor" href="#症状-→-证据-→-处理-→-完成标准-1" aria-label="Permalink to &quot;症状 → 证据 → 处理 → 完成标准&quot;">​</a></h3><p><strong>症状</strong>：事故复盘写了三页，结论是「模型抽风」。 <strong>证据</strong>：事故时间窗内没有可导出的 trace；请求只有状态码日志，没有 token 用量与工具调用记录。 <strong>处理</strong>：按<a href="./observability.html">可观测性</a>补 correlation ID 贯穿与 span 记录；把「事故时间窗重放」写进复盘模板。 <strong>完成标准</strong>：下次同类事故，复盘第一步是导出时间窗内 trace，而不是翻聊天记录。</p><h3 id="症状-→-证据-→-处理-→-完成标准-2" tabindex="-1">症状 → 证据 → 处理 → 完成标准 <a class="header-anchor" href="#症状-→-证据-→-处理-→-完成标准-2" aria-label="Permalink to &quot;症状 → 证据 → 处理 → 完成标准&quot;">​</a></h3><p><strong>症状</strong>：账单翻倍，没人知道是哪个功能、哪个用户、哪类请求造成的。 <strong>证据</strong>：成本只有厂商月账单一个数字；没有按请求/按功能维度的 usage 记账。 <strong>处理</strong>：按<a href="./cost-performance.html">成本与性能</a>建立每请求成本追踪（usage 字段 → 记录 → 聚合），先有分解再谈优化。 <strong>完成标准</strong>：能把当月成本拆到「功能 × 模型 × 输入/输出/缓存」三个维度，并指出最大单项。</p><h3 id="反模式清单" tabindex="-1">反模式清单 <a class="header-anchor" href="#反模式清单" aria-label="Permalink to &quot;反模式清单&quot;">​</a></h3><ul><li><strong>证据表演</strong>：为了过评审临时拼凑截图与数字，事后不可重放——这是「看似成功但证据不足」在 Production 组的形态。</li><li><strong>五链全上</strong>：内部工具配上金融级审计与全量 trace 采样，把证据成本做成了新的运营负担。</li><li><strong>证据与系统脱钩</strong>：测试跑在 mock 上、trace 只在 staging 开——生产路径恰恰没有覆盖。</li></ul><h2 id="_5-资料库" tabindex="-1">5. 资料库 <a class="header-anchor" href="#_5-资料库" aria-label="Permalink to &quot;5. 资料库&quot;">​</a></h2><p>四级阅读路线：</p><ul><li><strong>Beginner</strong>：读本页症状路由表，对自己的系统做一次五问审计，找出最大缺口。</li><li><strong>Builder</strong>：进 <a href="./testing.html">测试</a> 与<a href="./observability.html">可观测性</a>——两条最先产生复利的证据链（改动安全 + 故障可解释）。</li><li><strong>Operator</strong>：进 <a href="./security.html">安全</a>、<a href="./cost-performance.html">成本与性能</a>、<a href="./deployment.html">部署与发布</a>，把风险、账单与回滚纳入日常。</li><li><strong>Researcher</strong>：读下面 L0/L1 级规范（OWASP、NIST、OTel），理解业界对「可靠 AI 运营」的框架化表达。</li></ul><h3 id="资源表" tabindex="-1">资源表 <a class="header-anchor" href="#资源表" aria-label="Permalink to &quot;资源表&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>证据层级</th><th>canonical URL</th><th>用途</th><th>支持的断言</th><th>下一步</th></tr></thead><tbody><tr><td>OWASP GenAI LLM Top 10 2026</td><td>L0（官方清单）</td><td><a href="https://genai.owasp.org/resource/owasp-genai-llm-top-10-2026/" target="_blank" rel="noreferrer">https://genai.owasp.org/resource/owasp-genai-llm-top-10-2026/</a></td><td>风险证据的业界基线</td><td>2026-08-04 发布，风险排序基于 7,714 起真实事故语料（retrievedAt 2026-09-01）</td><td><a href="./security.html">安全</a></td></tr><tr><td>NIST AI RMF 1.0</td><td>L0（官方框架）</td><td><a href="https://www.nist.gov/itl/ai-risk-management-framework" target="_blank" rel="noreferrer">https://www.nist.gov/itl/ai-risk-management-framework</a></td><td>治理层风险管理的志愿框架</td><td>2023-01-26 发布，自愿采用；生成式 AI Profile（NIST AI 600-1）2024-07-26 发布；NIST 官网注明 1.0 正随白宫 AI 行动计划修订（retrievedAt 2026-09-01）</td><td><a href="./security.html">安全</a> 治理节</td></tr><tr><td>OpenTelemetry GenAI 语义约定</td><td>L0（官方规范）</td><td><a href="https://github.com/open-telemetry/semantic-conventions-genai" target="_blank" rel="noreferrer">https://github.com/open-telemetry/semantic-conventions-genai</a></td><td>观测证据的属性命名基线</td><td>GenAI 约定 2026-06 迁入独立仓库，覆盖 GenAI 客户端/MCP/厂商特定约定（retrievedAt 2026-09-01）</td><td><a href="./observability.html">可观测性</a></td></tr><tr><td>evals 站</td><td>sibling（跨仓 owner）</td><td><a href="https://evals.zenheart.site/" target="_blank" rel="noreferrer">https://evals.zenheart.site/</a></td><td>评估方法论唯一 owner</td><td>本仓只保留发布门接入（bridge-register 2026-09-01）</td><td><a href="./evaluation.html">评估（桥接）</a></td></tr></tbody></table><h3 id="主动证伪与未决问题" tabindex="-1">主动证伪与未决问题 <a class="header-anchor" href="#主动证伪与未决问题" aria-label="Permalink to &quot;主动证伪与未决问题&quot;">​</a></h3><ul><li>证伪入口：如果你找到一个「能稳定运营却缺五类证据之一」的真实系统，说明该类证据的必要性假设有漏洞——先检查它是否用了本表之外的等价证据形式，再考虑修订本组出口。</li><li>未决：六链深度如何按业务风险分级（哪些场景可以明确豁免哪类证据），待各子章运行手册积累案例后回填。</li></ul><h3 id="learn-ai-到此为止-继续去哪" tabindex="-1">learn-ai 到此为止 / 继续去哪 <a class="header-anchor" href="#learn-ai-到此为止-继续去哪" aria-label="Permalink to &quot;learn-ai 到此为止 / 继续去哪&quot;">​</a></h3><ul><li>评估方法论、数据集构建、judge 与统计：<a href="https://evals.zenheart.site/" target="_blank" rel="noreferrer">evals</a>。</li><li>模型对齐与后训练如何影响风险行为：<a href="https://llm.zenheart.site/" target="_blank" rel="noreferrer">Learn LLM</a>。</li><li>出组之后的完整资源索引：<a href="./../../resources.html">资料库</a>。</li></ul>',46))])}const x=n(c,[["render",g]]);export{k as __pageData,x as default};
